def full(name, title, line, bullets=None):
    body = f"# {name}

{title} — {line}

## 概述

"
    if bullets:
        body += f"本仓库用于维护{title[2:]}的信息，包括：

"
        body += "".join(f"- {b}
" for b in bullets)
    else:
        body += "- 待补充
"
    body += "
## 许可

[CC BY 4.0](LICENSE)
"
    return body

